xql_query:
// ============================================================
// Rule: MS_Admin Group Modified
// Vendor: BeyondTrust
// Objective:
// Detect activity associated with MS_Admin Group Modified.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation
// Technique: T1098.007 - Account Manipulation: Additional Local or Domain Groups

// Fonte de dados: logs do BeyondTrust Password Safe
dataset = beyondtrust_passwordsafe_raw  

// Filtra eventos que envolvam o grupo "Administrators",
// onde a ação foi de modificação (e não adição de usuários)
| filter _raw_log contains "Administrators"
       and category = "Configure"
       and event_name = "Modify"

// Seleciona os campos relevantes
| fields user,             // Quem executou a alteração
         category,         // Categoria do evento
         user_name,        // Usuário afetado (se aplicável)
         event_name,       // Tipo de evento (Modify)
         group_name,       // Nome do grupo (deve ser Administrators)
         _raw_log          // Log bruto para contexto
